{"command": "cd /workspace && python3 - <<'PY'
import json

order = {"row_id":"O0000-03","order_id":"ORD-0000-03","batch":"web","currency":"USD","amount_cents":13899}
payments = [{"row_id":"P0000-03","event_id":"PE-0000-03-a","payment_id":"PAY-0000-03-a","order_id":"ORD-0000-03","currency":"USD","amount_cents":13899,"status":"failed"}]
refunds = []
expected = order["amount_cents"]

# dedupe by event_id
def dedupe(rows):
    seen=set(); out=[]
    for r in rows:
        if r["event_id"] in seen: continue
        seen.add(r["event_id"]); out.append(r)
    return out

dpay = dedupe(payments)
dref = dedupe(refunds)

dup = len(dpay)!=len(payments) or len(dref)!=len(refunds)

# counted payments: distinct succeeded payment_id
paid = {}
for r in dpay:
    if r["status"]=="succeeded":
        paid[r["payment_id"]]=r["amount_cents"]
gross = sum(paid.values())

ref_n = {}
for r in dref:
    if r["status"]=="succeeded" and r["payment_id"] in paid:
        ref_n[r["payment_id"]] = ref_n.get(r["payment_id"],0)+r["amount_cents"]
refund = sum(ref_n.values())

net = gross - refund

anom=set()
if gross<expected: anom.add("underpaid")
if gross>expected: anom.add("overpaid")
if len(paid)>1: anom.add("multiple_successful_payments")
if refund>gross: anom.add("over_refunded")
if any(r["status"]=="failed" for r in payments): anom.add("payment_failed")
if any(r["status"]=="pending" for r in payments): anom.add("payment_pending")
if any(r["status"]=="failed" for r in refunds): anom.add("refund_failed")
if any(r["status"]=="pending" for r in refunds): anom.add("refund_pending")
if dup: anom.add("duplicate_delivery")

if gross==0: state="unpaid"
elif refund>gross: state="over_refunded"
elif refund==gross: state="fully_refunded"
elif refund>0: state="partially_refunded"
elif gross<expected: state="underpaid"
elif gross>expected: state="overpaid"
else: state="paid"

source = [order["row_id"]] + [r["row_id"] for r in payments] + [r["row_id"] for r in refunds]

result = {
  "order_id": order["order_id"],
  "batch": order["batch"],
  "currency": order["currency"],
  "expected_cents": expected,
  "gross_paid_cents": gross,
  "refund_cents": refund,
  "net_cents": net,
  "state": state,
  "anomalies": sorted(anom),
  "payment_ids": sorted(paid.keys()),
  "refund_ids": sorted(ref_n.keys()),
  "source_rows": sorted(source),
}
print(json.dumps(result, indent=2))
payload={"task_id":"reconcile-ord-0000-03","artifact":{"kind":"json","value":result}}
open("payload.json","w").write(json.dumps(payload))
print("written payload.json")
PY
cat payload.json"}

